#include <mutex>
#include <condition_variable>
#include <optional>

namespace ws {
namespace log {

enum class Level {
  Debug,
  Info,
  Warn,
  Error,
  Fatal
};

enum class AppenderType {
  StdOut,
  File
};

class Event {
public:
  Event(Level level, std::string_view fileName, size_t lineNum, uint32_t threadId) : 
    level_(level), fileName_(fileName), lineNum_(lineNum), threadId_(threadId)
  {}

  Level Level() const { return level_; }
  std::string_view FileName() const { return fileName_; }
  size_t LineNum() const { return lineNum_; }
  uint32_t ThreadId() const { return threadId_; }

private:
  Level level_;
  std::string_view fileName_;
  size_t lineNum_;
  uint32_t threadId_;
};

template <typename T>
class BlockDeque {
public:
  BlockDeque(size_t capacity) : capacity_(capacity) {}

  void PushBack(const T& item) {
    std::unique_lock<std::mutex> lock(mutex_);
    deque_.push_back(item);
    condition_.notify_one();
  }

  std::optional<T> Pop() {
    std::unique_lock<std::mutex> lock(mutex_);
    condition_.wait(lock, [this] { return !deque_.empty(); });
    T item = deque_.front();
    deque_.pop_front();
    return item;
  }

private:
  size_t capacity_; 
  std::deque<T> deque_;
  std::mutex mutex_;
  std::condition_variable condition_;
};

class Formatter {
public:
  Formatter(std::string_view pattern) : pattern_(pattern) {}

  virtual std::string Format(const Level& level, const Event& event) = 0;

protected:
  std::string_view Pattern() const { return pattern_; }
private:
  std::string_view pattern_; 
};

class Appender {
public:
  Appender(std::shared_ptr<Formatter> formatter) : formatter_(formatter) {}

  virtual void Log(const Level& level, const Event& event) = 0;

protected:
  Formatter::Ptr formatter_; 
};

class Logger {
public:
  Logger(std::string_view name, Level level, size_t capacity, bool async_) : 
    name_(name), level_(level), capacity_(capacity), async_(async_)
  {
    if (async_) {
      event_deque_ = std::make_shared<BlockDeque<Event::Ptr>>(capacity_);
      worker_thread_ = std::thread([this] { SyncLog(); });
    }
  }

  ~Logger() {
    if (async_) {
      StopAsyncLogging();
      worker_thread_.join();
    }
  }

  void Log(Event::Ptr event) {
    if (event->Level() >= level_) {
      LogInternal(event);
    }
  }

private:
  void LogInternal(Event::Ptr event) {
    if (async_ && event_deque_) {
      event_deque_->PushBack(event);
    } else {
      SyncLog(event);
    }
  }

  void SyncLog(Event::Ptr event = nullptr) {
    while (true) {
        std::shared_ptr<Event> current_event;
        if (async_) {
            auto maybe_event = event_deque_->Pop();
            if (!maybe_event) break; 
            current_event = *maybe_event;
        } else {
          current_event = event;
        }
      // Process the event using appenders.
      for (const auto& appender : appenders_) {
        appender->Log(level_, *current_event);
      }
    }
  }

  void StopAsyncLogging() {
    if (async_ && event_deque_) {
      // Signal the worker thread to exit.
    }
  }

public:
  std::string_view Name() const { return name_; }
  Level Level() const { return level_; }
  size_t Capacity() const { return capacity_; }

  void AddAppender(std::shared_ptr<Appender> appender) {
    appenders_.push_back(appender);
  }
private:
  std::string_view name_;
  Level level_;
  size_t capacity_;
  bool async_;
  std::list<std::shared_ptr<Appender>> appenders_;
  std::shared_ptr<BlockDeque<Event::Ptr>> event_deque_; 
  std::thread worker_thread_;
};

}
} // namespace ws::log

